package com.nivor.note;
import com.nivor.note.dto.*;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/notes")public class NoteController{
private final NoteService service;public NoteController(NoteService s){service=s;}
@GetMapping public List<NoteResponse> list(@AuthenticationPrincipal UserDetails u,@RequestParam(required=false)String search,@RequestParam(required=false)Boolean favorite,@RequestParam(required=false)Boolean pinned,@RequestParam(required=false)String category,@RequestParam(required=false)String tag){return service.list(u.getUsername(),search,favorite,pinned,category,tag).stream().map(NoteResponse::from).toList();}
@GetMapping("/{id}")public NoteResponse get(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){return NoteResponse.from(service.get(u.getUsername(),id));}@PostMapping public ResponseEntity<NoteResponse> create(@AuthenticationPrincipal UserDetails u,@Valid@RequestBody NoteRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(NoteResponse.from(service.create(u.getUsername(),r)));}@PutMapping("/{id}")public NoteResponse update(@AuthenticationPrincipal UserDetails u,@PathVariable Long id,@Valid@RequestBody NoteRequest r){return NoteResponse.from(service.update(u.getUsername(),id,r));}
@PatchMapping("/{id}/favorite")public NoteResponse favorite(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){return NoteResponse.from(service.favorite(u.getUsername(),id));}@PatchMapping("/{id}/pin")public NoteResponse pin(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){return NoteResponse.from(service.pin(u.getUsername(),id));}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){service.delete(u.getUsername(),id);return ResponseEntity.noContent().build();}
}
